// client/src/features/dashboard/attendee/JoinSession.jsx
import React, { useEffect, useRef } from 'react';
import { useLocation, Link } from 'react-router-dom';
import '../../../styles/GlobalStyles.css';

const JoinSession = () => {
  // pull the “?link=” out of the URL
  const { search } = useLocation();
  const link       = new URLSearchParams(search).get('link');

  // container to mount Jitsi into
  const jitsiContainerRef = useRef(null);
  // keep API object so we can dispose it later
  const apiRef            = useRef(null);

  useEffect(() => {
    // if no link, do nothing—but return a no-op cleanup
    if (!link) {
      return () => {};
    }

    // Jitsi wants just a room name, not the full URL.
    // Grab everything after the last “/”
    const parts    = link.split('/');
    const roomName = parts[parts.length - 1] || parts[parts.length - 2];

    // Create the External API instance
    apiRef.current = new window.JitsiMeetExternalAPI('meet.jit.si', {
      roomName,
      parentNode: jitsiContainerRef.current,
      interfaceConfigOverwrite: {},  // customize if you like
      configOverwrite: {}            // customize if you like
    });

    // cleanup on unmount (or when link changes)
    return () => {
      if (apiRef.current) {
        apiRef.current.dispose();
      }
    };
  }, [link]);

  return (
    <div className="container">
      <div className="card" style={{ height: '800px' }}>
        <h2>Live Session</h2>

        {!link && (
          <p style={{ color: 'red' }}>No session link provided.</p>
        )}

        {/* this <div> is where Jitsi will be injected */}
        <div
          ref={jitsiContainerRef}
          style={{ width: '100%', height: '100%' }}
        />

        <Link to="/attendee/dashboard">
          <button className="btn" style={{ marginTop: '1rem' }}>
            Back to Dashboard
          </button>
        </Link>
      </div>
    </div>
  );
};

export default JoinSession;
